 "Subscribers needed": "Nombre d’inscrits requis",
 "Run sql/prize_center.sql in Supabase to enable categories and subscriptions.": "Exécutez sql/prize_center.sql dans Supabase pour activer catégories et inscriptions.",
 "Open prize page": "Ouvrir la page du prix",
