 "From {n} points": "À partir de {n} points",
 "Required points": "Points requis",
 "How to subscribe": "Comment s'inscrire",
 "Gift": "Cadeau",
 "Challenge": "Défi",
 "Lottery": "Tombola",
 "Get the prize by paying points earned from your watch minutes. It usually costs more points, but you get more time — until the prize end date. The downside: it needs more watch points.": "Obtenez le prix en payant des points gagnés grâce à vos minutes de visionnage. Cela coûte généralement plus de points, mais vous disposez de plus de temps — jusqu'à la date de fin du prix. L'inconvénient : il faut davantage de points de visionnage.",
 "Subscribe with fewer points, but complete the required actions: watch specific titles, share them, bring friends to register, or collect a number of watch points in a set time. Light on points and fast — but the number of winners is limited to those who finish the conditions first.": "Inscrivez-vous avec moins de points, mais accomplissez les actions requises : regarder des titres précis, les partager, faire inscrire des amis ou accumuler un certain nombre de points de visionnage dans un délai donné. Peu coûteux en points et rapide — mais le nombre de gagnants est limité à ceux qui terminent les conditions en premier.",
 "Subscribe with the fewest points — just meet the conditions and win the draw once the required number of participants is reached. The lowest points cost and the most valuable prizes, but the draw is slow: it only happens when enough members join, and winning takes luck.": "Inscrivez-vous avec le moins de points — respectez simplement les conditions et remportez le tirage une fois le nombre de participants requis atteint. Le coût en points le plus bas et les prix les plus précieux, mais le tirage est lent : il n'a lieu que lorsqu'assez de membres participent, et gagner demande de la chance.",
 "Available from {start} to {end}": "Disponible du {start} au {end}",
 "From {date}": "À partir du {date}",
 "Limited to {n} winners": "Limité à {n} gagnants",
 "The draw starts once {n} members join": "Le tirage a lieu dès que {n} membres participent",
