 "You won the draw!": "Vous avez gagné le tirage !",
 "Conditions completed — you won!": "Conditions remplies — vous avez gagné !",
 "Subscription modes are not set up yet. Run sql/prize_modes.sql in Supabase.": "Les modes d'inscription ne sont pas encore configurés. Exécutez sql/prize_modes.sql dans Supabase.",
 "Share the {type} with TMDB ID {id}": "Partager le {type} avec l'ID TMDB {id}",
 "Bring {n} new member(s) to CineAura": "Amener {n} nouveau(x) membre(s) sur CineAura",
 "Subscription modes": "Modes d'inscription",
 "Every prize needs at least one mode. Gift keeps a start and an end date, challenge runs longer but is limited by quantity, and lottery has no end date and is limited by the number of winners.": "Chaque prix requiert au moins un mode. Le mode cadeau a une date de début et de fin, le défi dure plus longtemps mais est limité en quantité, et la tombola n'a pas de date de fin et est limitée par le nombre de gagnants.",
 "Add mode": "Ajouter un mode",
