 "Public or exclusive recommendations": "Recommandations publiques ou exclusives",
 "1 minute watched — yours or through your link — = 1 point": "1 minute regardée — par vous ou via votre lien — = 1 point",
 "5 link shares = 1 point": "5 partages de lien = 1 point",
 "5 new members registered through your links = 1 point": "5 nouveaux membres inscrits via vos liens = 1 point",
