 "Discount codes": "Codes de réduction",
 "Each code lowers the points required by 10%–80%. A member who enters a wrong code three times cannot enter codes for 24 hours.": "Chaque code réduit les points requis de 10 % à 80 %. Un membre qui saisit trois fois un code erroné ne peut plus en saisir pendant 24 heures.",
