 "coupon {code}": "coupon {code}",
 "This part of the panel needs the latest SQL: run content.sql, iptv_lists.sql, point_codes.sql, market.sql, packages.sql and then panel_admin.sql in the Supabase SQL editor.": "Cette partie du panel a besoin du dernier SQL : exécutez content.sql, iptv_lists.sql, point_codes.sql, market.sql, packages.sql puis panel_admin.sql dans l'éditeur SQL de Supabase.",
