 "The members you name get these points by themselves as soon as you save, without typing the serial. Each one counts as one use.": "Les membres que vous nommez reçoivent ces points automatiquement dès l’enregistrement, sans saisir le numéro de série. Chacun compte pour une utilisation.",
 "The members you name find this discount filled in by itself on their next prize entry that costs points, without typing the serial; they can keep it for another prize.": "Les membres que vous nommez trouvent cette réduction appliquée automatiquement lors de leur prochaine participation à un prix qui coûte des points, sans saisir le numéro de série ; ils peuvent la garder pour un autre prix.",
